      intro: 'Darkroomは、ブラウザーのタブで動作するマルチトラック動画エディターです。キャンバスとフレームレートを指定してプロジェクトを作成し、動画、画像、音声ファイルをメディアビンにドロップして、重ねたトラック上に配置し、フレーム単位でトリミングや分割を行い、カラーグレーディングやキーイングを施し、タイトル、トランジション、字幕を追加し、トラックごとのミキサーで音声をミックスしたら、完成したタイムラインを当社のレンダリングサーバーに渡します。サーバーではffmpegが編集全体を一つのフィルターグラフとして構築し、MP4のH.264またはHEVCにエンコードします。音声のみのプロジェクトの場合はMP3またはWAVにエンコードします。編集中に見ているプレビューは、お使いのGPU上でWebGL2によりリアルタイムに合成されます。エクスポートはそのプレビューと照合されるため、見たとおりの結果が得られます。',
      whatItDoes: [
        'フレーム精度のマルチトラックタイムラインを備えています：トリミング、分割、リップル削除、レーザー、スリップ、スライド、ロール、リップル編集、マーカー、グループ化、トラックのロック・ソロ・非表示、動画からの音声の切り離し。',
        'トラックを重なり順に合成し、クロップ、フィット、トランスフォーム、Lumetri風のカラーグレーディング（露出、コントラスト、彩度、色温度、色合い、自然な彩度）、3D LUT、スポイト付きクロマキー、不透明度、八つのブレンドモードを適用します。',
        '位置、スケール、回転、不透明度、音量、パン、エフェクトのパラメーターを、キーフレームと五種類のイージングカーブでアニメーション化します。十五種類のトランジションと、テキストレイヤーとシェイプレイヤーで作るタイトルクリップも追加できます。',
        'トラックごとのフェーダー、パン、三バンドEQ、コンプレッサーとライブメーターで音声をミックスし、マスターバスではダッキングと、ストリーミング、ポッドキャスト、放送向けのラウドネスプリセットを使えます。',
        '当社のGPU上のWhisperで字幕を生成し、字幕レーンで編集して、映像に焼き込むか、SRTまたはVTTのサイドカーファイルとしてエクスポートします。',
        'AAC音声付きのH.264またはHEVCのMP4、またはMP3やWAVを、キャンバスサイズのまま、または720、1080、1440、2160ラインに拡大縮小してエクスポートし、進行状況の確認と再レンダリングができるエクスポートパネルも備えています。',
      ],
