        '正直なエクスポート：ハードウェアエンコードかソフトウェアエンコードかはリアルタイムのテストで選ばれ、HEVCはごまかさずに拒否し、プランでレンダリングできない解像度は黙って画質を下げるのではなくエラーになります。',
        '一つのアカウント、一つの場所：編集中の同じファイルを文字起こし、圧縮、メタデータ削除にかけられ、ナレーションや字幕も同じGPUサーバーで生成できます。',
