      privacyNote: 'Darkroomは、プロジェクトが存在する限りメディアを当社のサーバーに保管します。アップロードしたファイルはアセットとしてメディアビンに入り、サーバーはそこからプレビュー用プロキシ、フィルムストリップ、波形のピークを作成し、エクスポートはレンダリングホスト上でffmpegによりoutputs/<jobId>/に作成されます。字幕を依頼すると、音声は当社自身のGPU上のWhisperに送られ、生成されたキューはプロジェクトとともに保存されます。プロジェクトのドキュメント、アセット、バージョン、エクスポートは、エディターまたはアカウントページから削除できます。ゲストのファイルは24時間保存されます。無料アカウントなら24時間から2年までの間で選べます。アップロードされた動画と音声は、当社自身のサーバーでの自動解析ステップも通ります。第三者のAIプロバイダーには何も送信されず、どのファイルも学習には使用されません。',
