        'IFD1に埋め込まれたプレビュー用サムネイルを削除します。これは画像の小さな別コピーで、多くの編集ソフトではトリミングしても残ります。',
        'XMPパケット（作成ツール、編集履歴、キーワード、評価）、IPTCレコード（作成者、著作権、キャプション）、Photoshopのリソースブロック、各社のメーカーノート、ICCカラープロファイルを削除します。',
        '先にEXIFの向き情報をピクセルに適用するため、回転タグに頼っていたスマートフォンの写真が、タグを削除した後に横向きになることはありません。',
