        'メタデータの処理は、変換後のファイルに対するexiftool -overwrite_original -all=です。-all=は書き込み可能なすべてのグループを一度に削除します：EXIF（IFD0、ExifIFD、GPS、InteropIFD）、IFD1のサムネイル、XMP、IPTC、Photoshop IRB、ICC_Profile、メーカーノート、そしてExifToolが書き込み方を知っているすべてのAPPセグメントです。JPEGデコーダーが必要とするJFIFとAdobe APP14のセグメントはそのまま残ります。これらはピクセルの配置を記述するもので、あなたについての情報ではありません。',
