      intro: 'HTTP Live Streamingは、動画を複数の画質の短いセグメントのプレイリストとして配信するため、プレーヤーはすばやく再生を始め、回線状況に応じて画質段階を切り替えられます。このパッケージを手作業で作るには、キーフレームを揃えて各レンディションをエンコードし、それらをセグメントに分割し、すべてのバリアントを正しく記述したマスタープレイリストを書く必要があります。このページはその作業をすべて行います。アップロードされたファイルを調べ、ソースとプランで使える画質段階を提示し、それぞれをlibx264とAACで2秒のMPEG-TSセグメントにエンコードします。必要に応じて、当社自身のWhisper文字起こしによる字幕、ストーリーボードのスプライトシート、スクラブ用のIフレームプレイリストを追加し、すべてを任意の静的ホストに展開できるtar.gzまたはzipにまとめます。',
