        '字幕には文字起こしツールと同じWhisperモデル（whisper-ctranslate2、medium）を使います。主トラックはcaptions/<lang>/auto.vttに、一つのセグメントだけのsubs.m3u8ラッパー付きで書き出され、マスターからEXT-X-MEDIA TYPE=SUBTITLESとして参照されます。37言語のリストから最大3つの追加言語が、ローカルのOllamaモデル（translategemma 12bのビルド）によってセグメントごとに翻訳されます。翻訳の失敗は警告として記録され、ジョブの失敗にはなりません。',
        'ストーリーボードはffmpegの一回の処理です。長さに応じてNを5、10、15秒（10分未満、30分未満、それ以上）としてfps=1/Nを適用し、16:9にパディングした160 x 90のタイルを、JPEGスプライト一枚あたり10 x 10のグリッドに並べ、#xywhキュー付きのstoryboard.vttも作成します。Iフレームプレイリストはキーフレームだけを240pで再エンコードし（select=eq(pict_type,I)、libx264 CRF 30、4秒のセグメント）、EXT-X-I-FRAME-STREAM-INFとして記載されます。',
        'マスターには、EXT-X-VERSION:6、EXT-X-INDEPENDENT-SEGMENTS、そして制作者、サイト、著作権者を示す三つのEXT-X-SESSION-DATA項目が含まれます。report.jsonには、解析結果、セグメント数とバイトサイズ付きのバリアント、警告、タイムスタンプが記録されます。',
